def describePainting(segments):
    diff = {}
    for s, e, c in segments:
        diff[s] = diff.get(s, 0) + c
        diff[e] = diff.get(e, 0) - c
    out = []
    cur = 0
    prev = None
    for x in sorted(diff):
        if prev is not None and cur > 0:
            out.append([prev, x, cur])
        cur += diff[x]
        prev = x
    return out

