def describePainting(segments):
    if not segments:
        return []
    lo = min(s for s, e, c in segments)
    hi = max(e for s, e, c in segments)
    out = []
    cur_set = None
    start = None
    for x in range(lo, hi):
        ids = frozenset(i for i, (s, e, c) in enumerate(segments) if s <= x < e)
        if ids != cur_set:
            if cur_set:
                out.append([start, x, sum(segments[i][2] for i in cur_set)])
            cur_set = ids
            start = x
    if cur_set:
        out.append([start, hi, sum(segments[i][2] for i in cur_set)])
    return out

